// bench_module.js -- E3 module bench logic (.specify/test_bench/tasks_extensions.md).
// Patch: bench_module.maxpat (generated by make_module_bench.py). Classic js, ES5.
//
// Inlets:  0  OSC from [udpreceive 7473]:  /ping  /run <job dir>  /close
//          1  Max errors: [error 1] -> [deferlow] -> [prepend bench_error]
//          2  per-frame bang from [r draw] (vs_render's qmetro)
// Outlet:  0  OSC to [udpsend 127.0.0.1 7474]:  /pong  /done <dir>  /busy <dir>  /closing
//
// A "module" job: load the wrapper (module bpatcher wired to r bench_minK /
// s bench_moutK) into the cordless slot, then run a frame timeline:
//   W        open capture gates                       (all outlets)
//   W+1      write base_outK.jxf
//   W+2      send params as control messages into inlet 0
//   +S       read back attributes from the module's jit.gl.pix objects
//   +1       send control message `bypass 1` (the documented path)
//   +S       read back `bypass` on every pix; send `bypass 0`
//   +S       bypass jsui msg_int 1 (what a click does)
//   +S       read back `bypass` on every pix; open gates
//   +1       write bypassed_outK.jxf; jsui 0; finish
// Inputs are re-sent every frame (a pix renders when it receives a texture).

autowatch = 1;
inlets = 3;
outlets = 1;

var N_OUT = 4;
var N_IN = 5;
var MAX_ERRORS = 50;

var job = null, jobDir = null, errors = [], frames = 0, t0 = 0;
var timeline = [], extra = {}, watchdog = null, inErrorHandler = false;

function anything() {
    var args = arrayfromargs(arguments);
    if (inlet === 0) guarded(function () { handleOsc(messagename, args); });
}

function bench_error() {
    if (inErrorHandler || !job) return;
    inErrorHandler = true;
    try {
        if (errors.length < MAX_ERRORS) {
            var w = arrayfromargs(arguments);
            if (w.length && w[0] === "error") w.shift();
            errors.push(w.join(" "));
        }
    } catch (e) { }
    inErrorHandler = false;
}

function bang() {
    if (inlet !== 2 || !job) return;
    frames++;
    guarded(onFrame);
}

function guarded(f) {
    try { f(); } catch (e) {
        if (job) finish("error", "bench_module.js exception: " + e);
        else post("bench_module.js exception: " + e + "\n");
    }
}

function handleOsc(address, args) {
    if (address === "/ping") {
        outlet(0, "/pong");
    } else if (address === "/run") {
        var dir = String(args.join(" "));
        if (job) { outlet(0, "/busy", dir); return; }
        startJob(dir);
    } else if (address === "/eval") {
        // local debugging hook (localhost UDP only): run <file>.js, write
        // <file>.out.json with its return value or the exception
        var path = String(args.join(" ")), res;
        try { res = { ok: true, value: eval(readText(path)) }; }
        catch (e) { res = { ok: false, error: String(e) }; }
        writeText(path + ".out.json", JSON.stringify(res, null, 1));
        outlet(0, "/evaled", path);
    } else if (address === "/probe") {
        probe(String(args.join(" ")));
    } else if (address === "/close") {
        if (job) { outlet(0, "/busy", "close"); return; }
        outlet(0, "/closing");
        var pat = this.patcher;
        var t = new Task(function () { pat.wclose(); }, this);
        t.schedule(50);
    }
}

// ------------------------------------------------------------ job

function startJob(dir) {
    jobDir = dir; errors = []; frames = 0; extra = {}; t0 = Date.now();
    var text = readText(dir + "/job.json"), parsed = null;
    try { parsed = text === null ? null : JSON.parse(text); } catch (e) { parsed = null; }
    job = parsed || { id: "unknown", mode: "invalid" };
    if (!parsed) return finish("error", "cannot read or parse " + dir + "/job.json");
    if (job.mode !== "module") return finish("error", "mode '" + job.mode + "' not supported by the module bench");

    for (var k = 1; k <= N_OUT; k++) {
        obj("bench_mgate" + k).message(0);
        obj("bench_mcap" + k).message("dim", 1, 1);
    }
    var ins = job.inputs || [];
    for (var i = 0; i < ins.length && i < N_IN; i++) {
        var m = obj("bench_mmat" + (i + 1));
        m.message("read", jobDir + "/" + ins[i]);
        m.message("bang");
    }
    // Unload first, load next frame: `replace` creates the new patcher before
    // freeing the old one, so a module whose pix has a fixed @name collides
    // with itself ("name ... already in use. ob3d does not allow multiple
    // bindings", 2026-09-22).
    this.patcher.message("script", "sendbox", "bench_mslot", "replace", "bench_module_empty.maxpat");
    messnamed("bench_vsctl", "enable", 1);
    buildTimeline();
    startWatchdog();
}

function buildTimeline() {
    var W = job.warmup || 10, S = job.settle || 6, f = W;
    timeline = [];
    function at(frame, fn) { timeline.push([frame, fn]); }
    var pat = this.patcher;
    at(1, function () { pat.message("script", "sendbox", "bench_mslot", "replace", job.wrapper); });
    at(2, function () {
        extra.pix = pixList().map(function (p) { return String(p.getattr("name")); });
        extra.jsui_found = !!bypassJsui();
    });
    f = Math.max(W, 4);
    at(f, function () { openGates(); });
    at(f + 1, function () { writeCaps("base"); });
    f += 2;
    // one control message per frame: a burst in a single frame gave
    // nondeterministic readbacks (2026-09-22), so don't test that way
    var ps = job.params || [];
    for (var i = 0; i < ps.length; i++) {
        (function (msg) { at(f + i, function () { messnamed.apply(null, ["bench_min1"].concat(msg)); }); })(ps[i]);
    }
    f += ps.length + S;
    at(f, function () {
        extra.params_readback = readback(job.readback || {});
        extra.controls_readback = readControls(job.controls || []);
    });
    f += 1;
    at(f, function () { messnamed("bench_min1", "bypass", 1); });
    f += S;
    at(f, function () {
        extra.bypass_msg_readback = readBypass();
        messnamed("bench_min1", "bypass", 0);
    });
    f += S;
    at(f, function () { var j = bypassJsui(); if (j) j.message("int", 1); });
    f += S;
    at(f, function () {
        extra.bypass_jsui_readback = bypassJsui() ? readBypass() : null;
        resetCaps();
        openGates();
    });
    at(f + 1, function () {
        writeCaps("bypassed");
        var j = bypassJsui();
        if (j) j.message("int", 0);
    });
    at(f + 2, function () { finish(errors.length ? "error" : "ok"); });
}

function onFrame() {
    feedInputs();
    for (var i = 0; i < timeline.length; i++) {
        if (timeline[i][0] === frames) timeline[i][1]();
        if (!job) return;                                // finished mid-list
    }
}

function feedInputs() {
    var n = Math.min((job.inputs || []).length, N_IN);
    for (var k = 1; k <= n; k++) messnamed("bench_min" + k, "jit_gl_texture", "bench_mtex" + k);
}

function sendParams() {
    var ps = job.params || [];
    for (var i = 0; i < ps.length; i++) messnamed.apply(null, ["bench_min1"].concat(ps[i]));
}

// ------------------------------------------------------------ capture

function openGates() { for (var k = 1; k <= N_OUT; k++) obj("bench_mgate" + k).message(1); }

function resetCaps() { for (var k = 1; k <= N_OUT; k++) obj("bench_mcap" + k).message("dim", 1, 1); }

function writeCaps(tag) {
    var got = [];
    for (var k = 1; k <= N_OUT; k++) {
        obj("bench_mgate" + k).message(0);
        var m = obj("bench_mcap" + k);
        var d = m.getattr("dim");
        if (d && !(d[0] === 1 && d[1] === 1)) {
            m.message("write", jobDir + "/" + tag + "_out" + k + ".jxf");
            got.push(k);
        }
    }
    if (!extra.outputs) extra.outputs = {};
    extra.outputs[tag] = got;
}

// ------------------------------------------------------------ introspection

function moduleSubpatcher() {
    var slot = obj("bench_mslot");
    var wrap = slot ? slot.subpatcher() : null;
    if (!wrap) return null;
    // In js a loaded bpatcher reports maxclass "patcher" (probe, 2026-09-22),
    // so find the module by the scripting name the wrapper gives it.
    for (var o = wrap.firstobject; o; o = o.nextobject) {
        if (o.varname === "bench_module") return o.subpatcher();
    }
    return null;
}

function collect(p, pred, out) {
    for (var o = p.firstobject; o; o = o.nextobject) {
        if (pred(o)) out.push(o);
        if ((o.maxclass === "bpatcher" || o.maxclass === "patcher") && o.subpatcher()) {
            collect(o.subpatcher(), pred, out);
        }
    }
    return out;
}

function pixList() {
    var m = moduleSubpatcher();
    return m ? collect(m, function (o) { return o.maxclass === "jit.gl.pix"; }, []) : [];
}

function bypassJsui() {
    var m = moduleSubpatcher();
    if (!m) return null;
    var js = collect(m, function (o) {
        if (o.maxclass !== "jsui") return false;
        if (o.varname === "bypass") return true;             // f_ convention
        var fn = null;
        try { fn = o.getattr("filename"); } catch (e) { }
        return String(fn).indexOf("bypass_toggle") >= 0;
    }, []);
    return js.length ? js[0] : null;
}

// readback spec: {attr: [pix name suffixes that should carry it]}
function readback(spec) {
    var out = {}, pix = pixList();
    for (var attr in spec) {
        if (!spec.hasOwnProperty(attr)) continue;
        out[attr] = {};
        var sufs = spec[attr];
        for (var i = 0; i < pix.length; i++) {
            var name = String(pix[i].getattr("name"));
            for (var s = 0; s < sufs.length; s++) {
                if (endsWith(name, sufs[s])) {
                    var v = pix[i].getattr(attr);
                    out[attr][name] = (v && v.length !== undefined) ? v[0] : v;
                }
            }
        }
    }
    return out;
}

function readBypass() {
    var out = {}, pix = pixList();
    for (var i = 0; i < pix.length; i++) {
        var v = pix[i].getattr("bypass");
        out[String(pix[i].getattr("name"))] = (v && v.length !== undefined) ? v[0] : v;
    }
    return out;
}

// UI controls (live.dial / live.numbox ...) by scripting name: their own value
function readControls(names) {
    var out = {}, m = moduleSubpatcher();
    if (!m) return out;
    var want = {};
    for (var i = 0; i < names.length; i++) want[names[i]] = true;
    var objs = collect(m, function (o) { return want[o.varname] === true; }, []);
    for (var j = 0; j < objs.length; j++) {
        var v = null;
        try { v = objs[j].getvalueof(); } catch (e) { v = "getvalueof failed"; }
        out[objs[j].varname] = (v && v.length !== undefined && typeof v !== "string") ? v[0] : v;
    }
    return out;
}

function endsWith(s, suf) { return s.length >= suf.length && s.substr(s.length - suf.length) === suf; }

// ------------------------------------------------------------ probe
// /probe <file>: dump what js can see (slot, wrapper, module objects) as
// JSON -- for writing introspection against facts, not guesses.
function describe(p, depth) {
    var out = [];
    if (!p || depth > 3) return out;
    for (var o = p.firstobject; o; o = o.nextobject) {
        var d = { maxclass: o.maxclass, varname: o.varname };
        try { d.has_sub = !!o.subpatcher(); } catch (e) { d.sub_err = String(e); }
        if (d.has_sub && o.maxclass !== "jit.gl.pix") d.children = describe(o.subpatcher(), depth + 1);
        out.push(d);
    }
    return out;
}

function probeValues() {
    var out = [], m = moduleSubpatcher();
    if (!m) return "no module";
    var objs = collect(m, function (o) {
        return o.maxclass === "live.dial" || o.maxclass === "live.numbox" || o.maxclass === "attrui";
    }, []);
    for (var i = 0; i < objs.length; i++) {
        var o = objs[i], d = { maxclass: o.maxclass, varname: o.varname };
        try { d.value = o.getvalueof(); } catch (e) { d.value_err = String(e); }
        if (o.maxclass === "attrui") { try { d.attr = o.getattr("attr"); } catch (e) { d.attr_err = String(e); } }
        out.push(d);
    }
    return out;
}

function probe(file) {
    var info = { slot: null };
    try { info.values = probeValues(); } catch (e) { info.values_err = String(e); }
    try {
        var slot = obj("bench_mslot");
        info.slot_class = slot ? slot.maxclass : null;
        info.slot = describe(slot ? slot.subpatcher() : null, 0);
    } catch (e) { info.error = String(e); }
    writeText(file, JSON.stringify(info, null, 1));
    outlet(0, "/probed", file);
}

// ------------------------------------------------------------ finish

function startWatchdog() {
    var id = job.id;
    watchdog = new Task(function () {
        if (job && job.id === id) finish("stalled", "timeline not finished within " +
                                         (job.timeout_ms || 15000) + " ms (" + frames + " frames seen)");
    }, this);
    watchdog.schedule(job.timeout_ms || 15000);
}

function finish(status, extraError) {
    if (extraError) errors.push("bench_module: " + extraError);
    if (watchdog) { watchdog.cancel(); watchdog = null; }
    for (var k = 1; k <= N_OUT; k++) { var g = obj("bench_mgate" + k); if (g) g.message(0); }
    var result = { id: job.id, status: status, errors: errors, frames_rendered: frames,
                   elapsed_ms: Date.now() - t0 };
    for (var key in extra) if (extra.hasOwnProperty(key)) result[key] = extra[key];
    var dir = jobDir;
    if (!writeText(dir + "/result.json", JSON.stringify(result, null, 2))) {
        post("bench_module: could not write result.json in " + dir + "\n");
    }
    job = null; jobDir = null; timeline = [];
    outlet(0, "/done", dir);
}

function obj(name) {
    var o = this.patcher.getnamed(name);
    if (!o) post("bench_module: no object named " + name + "\n");
    return o;
}

function readText(path) {
    var f = new File(path, "read");
    if (!f.isopen) return null;
    var out = "";
    while (f.position < f.eof) out += f.readstring(Math.min(1024, f.eof - f.position));
    f.close();
    return out;
}

function writeText(path, s) {
    var f = new File(path, "write", "TEXT");
    if (!f.isopen) return false;
    f.eof = 0; f.writestring(s); f.close();
    return true;
}
